    log_delay = x_i[1] ? 0 : negative_infinity();
  } else if (x_i[1]) {
    log_delay = primarycensored_loglogistic_lccdf(u | theta[1], theta[2]);
  } else {
    log_delay = primarycensored_loglogistic_lcdf(u | theta[1], theta[2]);
  }
