  real shape = params[2];
  real log_ratio = shape * (log(t) - log(params[1]));
  real log_t_F_T = log(t) - log1p_exp(-log_ratio);
  return [
    log_t_F_T,
    log_t_F_T + log(loglogistic_moment_ratio(1 / shape, log_ratio, 1e-16))
  ]';
}
real primarycensored_loglogistic_uniform_lcdf(data real d, real q,
                                              array[] real params,
                                              data real pwindow) {
  vector[2] terms_d = primarycensored_loglogistic_uniform_terms(d, params);
  vector[2] terms_q = primarycensored_loglogistic_uniform_terms(q, params);
  real log_cdf = primarycensored_uniform_lcdf_from_terms(
    terms_d, terms_q, pwindow
  );
  if (loglogistic_window_ill_conditioned(terms_d[1], terms_q[1], d, pwindow,
                                         log_cdf)) {
    return loglogistic_numeric_lcdf(d | params, pwindow);
  }
  return fmin(log_cdf, 0);
}
real primarycensored_exptilt_lcdf(data real d, int dist_id,
                                  array[] real params, data real pwindow,
                                  real rho) {
  vector[4] context = rep_vector(0, 4);
  if (primarycensored_exptilt_form(d, dist_id, rho, pwindow) == 0) {
    context = log_tilt_transform_context(dist_id, -rho, params);
  }
  return primarycensored_exptilt_lcdf_shared(
    d, dist_id, params, pwindow, rho, context
  );
}
real primarycensored_analytical_lcdf_raw(data real d, int dist_id,
                                         array[] real params,
                                         data real pwindow,
                                         int primary_id,
                                         array[] real primary_params) {
  real q = max({d - pwindow, 0});

  if (check_for_exptilt(dist_id, primary_id)) {
    if (!check_for_tilt_transform(dist_id, -primary_params[1], params)) {
      reject(
        "The tilted delay distribution does not exist for tilt ",
        primary_params[1], ". Use the numerical path, see ",
        "check_for_analytical_params()."
      );
    }
    return primarycensored_exptilt_lcdf(
      d | dist_id, params, pwindow, primary_params[1]
    );
  }
  if (check_for_tlogis(dist_id, primary_id)) {
    return primarycensored_tlogis_lcdf(
      d | dist_id, params, pwindow, primary_params[1], primary_params[2]
    );
  }
  if (check_for_gumbel(dist_id, primary_id)) {
    if (!check_for_gumbel_params(
          dist_id, params, primary_params[1], primary_params[2])) {
      reject(
        "The truncated Gumbel solution does not apply for mu ",
        primary_params[1], " and beta ", primary_params[2],
        ". Use the numerical path, see check_for_analytical_params()."
      );
    }
    return primarycensored_gumbel_lcdf(
      d | dist_id, params, pwindow, primary_params[1], primary_params[2]
    );
  }
  if (dist_id == 2 && primary_id == 1) {
    return primarycensored_gamma_uniform_lcdf(d | q, params, pwindow);
  } else if (dist_id == 1 && primary_id == 1) {
    return primarycensored_lognormal_uniform_lcdf(d | q, params, pwindow);
  } else if (dist_id == 3 && primary_id == 1) {
    return primarycensored_weibull_uniform_lcdf(d | q, params, pwindow);
  } else if (dist_id == 5 && primary_id == 1) {
    return primarycensored_gengamma_uniform_lcdf(d | q, params, pwindow);
  } else if (dist_id == 29 && primary_id == 1) {
    return primarycensored_loglogistic_uniform_lcdf(d | q, params, pwindow);
  } else if (dist_id == 26) {
    // params = [boundaries (K+1), pmf (K)]; length 2*K + 1.
    int K = (size(params) - 1) %/% 2;
    return discretestep_lcdf(
      d | to_vector(segment(params, 1, K + 1)),
          to_vector(segment(params, K + 2, K)),
          primary_id, primary_params, pwindow
    );
  } else if (dist_id == 27 || dist_id == 28) {
    // params = [boundaries (K+1), hazards (K)]; length 2*K + 1. The last
    // hazard must equal 1. RW (27) and RE (28) only differ in their
    // prior so they share this likelihood dispatch.
    int K = (size(params) - 1) %/% 2;
    return discretehazard_lcdf(
      d | to_vector(segment(params, 1, K + 1)),
          to_vector(segment(params, K + 2, K)),
          primary_id, primary_params, pwindow
    );
  }
  return negative_infinity();
}
real primarycensored_analytical_lcdf(data real d, int dist_id,
                                           array[] real params,
                                           data real pwindow, data real L,
                                           data real D, int primary_id,
                                           array[] real primary_params) {
  if (d <= L) return negative_infinity();
  if (d >= D) return 0;

  real result = primarycensored_analytical_lcdf_raw(
    d, dist_id, params, pwindow, primary_id, primary_params
  );

  // Apply truncation normalization, also for a finite negative L for delays
  // on the reals
  if (!is_inf(D) || L > 0
      || (!is_inf(L) && !dist_has_positive_support(dist_id))) {
    vector[2] bounds = primarycensored_truncation_bounds(
      L, D, dist_id, params, pwindow, primary_id, primary_params
    );
    real log_cdf_L = bounds[1];
    real log_cdf_D = bounds[2];

    real log_normalizer = primarycensored_log_normalizer(log_cdf_D, log_cdf_L, L);
    result = primarycensored_apply_truncation(result, log_cdf_L, log_normalizer, L);
  }

  return result;
}
real primarycensored_analytical_cdf(data real d, int dist_id,
                                          array[] real params,
                                          data real pwindow, data real L,
                                          data real D, int primary_id,
                                          array[] real primary_params) {
  return exp(primarycensored_analytical_lcdf(d | dist_id, params, pwindow, L, D, primary_id, primary_params));
}
int check_for_gumbel(int dist_id, int primary_id) {
  return primary_id == 4 && dist_id == 18;
}
int gumbel_n_terms(real log_s0) {
  int n = 2;
  while (n < 200
         && n * log_s0 - lgamma(n + 1) - fmax(log_s0, 0) >= log(1e-18)) {
    n += 1;
  }
  return n;
}
int check_for_gumbel_params(int dist_id, array[] real params, real mu,
                            real beta) {
  if (!check_for_gumbel(dist_id, 4)) return 0;
  if (!(beta > 0) || is_inf(beta) || is_nan(mu) || is_inf(mu)) return 0;
  real log_s0 = mu / beta;
  if (log_s0 > log(15)) return 0;
  real xi = gumbel_n_terms(log_s0) / beta;
  real size = xi * abs(params[1]) + 0.5 * square(xi * params[2]);
  return log(machine_precision()) + log1p(size) + exp(log_s0)
         <= log(1e-7);
}
real gumbel_log_sum_exp(real a, real b) {
  if (a == negative_infinity()) return b;
  if (b == negative_infinity()) return a;
  return log_sum_exp(a, b);
}
real gumbel_delay_lcdf(real x, array[] real params, int dist_id) {
  if (dist_has_positive_support(dist_id) && x <= 0) {
    return negative_infinity();
  }
  if (dist_id == 1) {
    if (lognormal_lcdf_underflows(x, params[1], params[2])) {
      return negative_infinity();
    }
    return primarycensored_log_std_normal_cdf(
      (log(x) - params[1]) / params[2]
    );
  } else if (dist_id == 4) {
    return log1m_exp(-params[1] * x);
  } else if (dist_id == 18) {
    return primarycensored_log_std_normal_cdf((x - params[1]) / params[2]);
  } else if (dist_id == 3) {
    if (params[1] * (log(x) - log(params[2])) < -700) {
      return negative_infinity();
    }
  } else if (dist_id == 2 || dist_id == 13) {
    real log_f = dist_id == 2
      ? gamma_lcdf_logx(log(x) + gamma_log_rate(params[2]), params[1])
      : gamma_lcdf_logx(log(x) - log2(), params[1] / 2);
    return log_f < -700 ? negative_infinity() : log_f;
  } else if (dist_id == 16 || dist_id == 19 || dist_id == 22) {
    // Inverse gamma, with the shape and scale of each family
    real shape = dist_id == 16 ? params[1] : params[1] / 2;
    real scale = dist_id == 16 ? params[2]
                 : (dist_id == 19 ? 0.5 : params[1] * square(params[2]) / 2);
    real log_f = gamma_lcdf_lccdf_logx(log(scale) - log(x), shape)[2];
    return log_f < -700 ? negative_infinity() : log_f;
  } else if (dist_id == 9) {
    if (x >= 1) {
      return 0;
    }
    if (x < params[1] / (params[1] + params[2])
        && params[1] * log(x) - log(params[1]) - lbeta(params[1], params[2])
           < -700) {
      return negative_infinity();
    }
  }
  return dist_lcdf(x | params, dist_id);
}
real gumbel_numeric_delay(real u, data real d, data real pwindow, real mu,
                          real beta) {
  return (d - pwindow) + beta * log1p(u * exp(-(mu - pwindow) / beta));
}
vector gumbel_numeric_point(real tau, real lo, real hi, real a,
                            data real d, data real pwindow, real mu,
                            real beta) {
  real x = lo + (hi - lo) * tau;
  if (mu >= pwindow) {
    return [gumbel_numeric_delay(a - log1m(x), d, pwindow, mu, beta), 0]';
  }
  return [d - x, tgumbel_lpdf(x | 0, pwindow, mu, beta)]';
}
vector primarycensored_gumbel_ode(real tau, vector y, data real d,
                                  data real pwindow, int dist_id,
                                  array[] real params, real mu, real beta,
                                  real lo, real hi, real a,
                                  real log_shift) {
  vector[2] point = gumbel_numeric_point(
    tau, lo, hi, a, d, pwindow, mu, beta
  );
  return rep_vector(
    (hi - lo)
    * exp(gumbel_delay_lcdf(point[1] | params, dist_id) + point[2] - log_shift),
    1
  );
}
real gumbel_numeric_piece_lcdf(data real d, int dist_id, array[] real params,
                               data real pwindow, real mu, real beta, real a,
                               real c, real log_shift) {
  if (log_shift == negative_infinity()) {
    return negative_infinity();
  }
  vector[1] y0 = rep_vector(0.0, 1);
  real integral = ode_rk45_tol(
    primarycensored_gumbel_ode, y0, 0.0, {1.0}, 1e-10, 1e-14, 200000,
    d, pwindow, dist_id, params, mu, beta, 0.0, c, a, log_shift
  )[1, 1];
  if (!(integral > 0)) {
    return negative_infinity();
  }
  return -a + log_shift + log(integral);
}
real gumbel_numeric_spike_lcdf(data real d, int dist_id, array[] real params,
                               data real pwindow, real mu, real beta) {
  real log_delta = (mu - pwindow) / beta + log_diff_exp(pwindow / beta, 0);
  real a = 0;
  if (dist_has_positive_support(dist_id) && d < pwindow) {
    // The delay CDF is 0 for u below the kink, where d - z is 0
    real log_uk = (mu - pwindow) / beta
                  + log_diff_exp((pwindow - d) / beta, 0);
    // The CDF is below exp(-1000) beyond u of 1000
    if (log_uk >= log_delta || log_uk > log(1000)) {
      return negative_infinity();
    }
    a = exp(log_uk);
  }
  real top = exp(log_delta);
  // A piece of at most 36 ends within 2^-53 of 1 in the upper quantile.
  // The lengths are literals so that they are not differentiated.
  real log_total = negative_infinity();
  int finished = 0;
  for (k in 1:300) {
    int big = top - a > 48;
    int j = 0;
    int last = top - a <= 12;
    real len = last ? top - a : (big ? 36.0 : 12.0);
    real log_f_end = gumbel_delay_lcdf(
      gumbel_numeric_delay(a + len, d, pwindow, mu, beta) | params, dist_id
    );
    real log_f_mid = gumbel_delay_lcdf(
      gumbel_numeric_delay(a + len / 2, d, pwindow, mu, beta)
      | params, dist_id
    );
    for (i in 1:30) {
      if (!(log_f_end - log_f_mid > 3)) {
        break;
      }
      if (last) {
        // Continue with pieces that are at most half of what is left
        last = 0;
        while (12.0 / pow(2, j) > len / 2) {
          j += 1;
        }
      } else {
        j += 1;
      }
      len = (big ? 36.0 : 12.0) / pow(2, j);
      log_f_end = gumbel_delay_lcdf(
        gumbel_numeric_delay(a + len, d, pwindow, mu, beta) | params, dist_id
      );
      log_f_mid = gumbel_delay_lcdf(
        gumbel_numeric_delay(a + len / 2, d, pwindow, mu, beta)
        | params, dist_id
      );
    }
    // The lengths of the pieces before the last are passed as literals
    if (last) {
      log_total = gumbel_log_sum_exp(
        log_total,
        gumbel_numeric_piece_lcdf(
          d | dist_id, params, pwindow, mu, beta, a, -expm1(-(top - a)),
          log_f_end
        )
      );
    } else {
      log_total = gumbel_log_sum_exp(
        log_total,
        gumbel_numeric_piece_lcdf(
          d | dist_id, params, pwindow, mu, beta, a,
          -expm1(-((big ? 36.0 : 12.0) / pow(2, j))), log_f_end
        )
      );
    }
    a += len;
    // The CDF is below exp(-1000) beyond u of 1000
    if (log_total == negative_infinity() && a > 1000) {
      return negative_infinity();
    }
    real slope = 2 * (log_f_end - log_f_mid) / len;
    if (last || a >= top
        || (slope < 0.99
            && -a + log_f_end - log1m(slope) < log_total + log(1e-15))) {
      finished = 1;
      break;
    }
  }
  if (!finished) {
    reject(
      "The truncated Gumbel numerical integral did not finish for d ", d,
      ", pwindow ", pwindow, ", mu ", mu, " and beta ", beta,
      ". The log CDF is extremely small, below about -1000, so the delay ",
      "distribution and the window are far apart."
    );
  }
  return log_total - tgumbel_log1m_exp_neg_exp(log_delta);
}
vector gumbel_numeric_z_limits(data real d, int dist_id, data real pwindow,
                               real mu, real beta) {
  real log_sw = (mu - pwindow) / beta;
  real z_low = fmax(0, mu - beta * log(745 + exp(log_sw)));
  real z_high = fmin(pwindow, fmax(mu, 0) + 46 * beta);
  if (dist_has_positive_support(dist_id)) {
    z_high = fmin(z_high, d);
  }
  return [z_low, z_high]';
}
real gumbel_z_log_integrand(real z, data real d, int dist_id,
                            array[] real params, data real pwindow, real mu,
                            real beta) {
  return gumbel_delay_lcdf(d - z | params, dist_id)
         + tgumbel_lpdf(z | 0, pwindow, mu, beta);
}
real gumbel_numeric_z_half(data real d, int dist_id, array[] real params,
                           data real pwindow, real mu, real beta,
                           real z_from, real z_to, real log_shift) {
  vector[1] y0 = rep_vector(0.0, 1);
  return ode_rk45_tol(
    primarycensored_gumbel_ode, y0, 0.0, {1.0}, 1e-10, 1e-14, 200000,
    d, pwindow, dist_id, params, mu, beta, z_from, z_to, 0.0, log_shift
  )[1, 1];
}
real gumbel_numeric_z_lcdf(data real d, int dist_id, array[] real params,
                           data real pwindow, real mu, real beta) {
  vector[2] z_limits = gumbel_numeric_z_limits(d, dist_id, pwindow, mu, beta);
  if (!(z_limits[2] > z_limits[1])) {
    return negative_infinity();
  }
  real z_low = z_limits[1];
  real z_high = z_limits[2];
  real step = (z_high - z_low) / 16;
  real z_peak = z_low;
  real log_shift = gumbel_z_log_integrand(
    z_low, d, dist_id, params, pwindow, mu, beta
  );
  for (i in 1:16) {
    real z = z_low + step * i;
    real g = gumbel_z_log_integrand(z, d, dist_id, params, pwindow, mu, beta);
    if (g > log_shift) {
      log_shift = g;
      z_peak = z;
    }
  }
  if (log_shift == negative_infinity()) {
    return negative_infinity();
  }
  // Golden section search around the best grid point
  real inv_phi = 0.6180339887498949;
  real lo = fmax(z_low, z_peak - step);
  real hi = fmin(z_high, z_peak + step);
  real z1 = hi - inv_phi * (hi - lo);
  real z2 = lo + inv_phi * (hi - lo);
  real g1 = gumbel_z_log_integrand(z1, d, dist_id, params, pwindow, mu, beta);
  real g2 = gumbel_z_log_integrand(z2, d, dist_id, params, pwindow, mu, beta);
  for (i in 1:40) {
    if (g1 > g2) {
      hi = z2;
      z2 = z1;
      g2 = g1;
      z1 = hi - inv_phi * (hi - lo);
      g1 = gumbel_z_log_integrand(z1, d, dist_id, params, pwindow, mu, beta);
    } else {
      lo = z1;
      z1 = z2;
      g1 = g2;
      z2 = lo + inv_phi * (hi - lo);
      g2 = gumbel_z_log_integrand(z2, d, dist_id, params, pwindow, mu, beta);
    }
  }
  if (g1 > log_shift && g1 >= g2) {
    log_shift = g1;
    z_peak = z1;
  } else if (g2 > log_shift) {
    log_shift = g2;
    z_peak = z2;
  }
  real integral = 0;
  if (z_peak > z_low) {
    integral += -gumbel_numeric_z_half(
      d, dist_id, params, pwindow, mu, beta, z_peak, z_low, log_shift
    );
  }
  if (z_high > z_peak) {
    // An upper limit at the window end or d is passed as data, to keep it
    // out of the sensitivities, which are singular at d for a delay CDF
    // with an infinite slope at 0. Local variables would be parameters.
    if (z_high >= (dist_has_positive_support(dist_id) ? fmin(pwindow, d)
                                                       : pwindow)) {
      integral += gumbel_numeric_z_half(
        d, dist_id, params, pwindow, mu, beta, z_peak,
        dist_has_positive_support(dist_id) ? fmin(pwindow, d) : pwindow,
        log_shift
      );
    } else {
      integral += gumbel_numeric_z_half(
        d, dist_id, params, pwindow, mu, beta, z_peak, z_high, log_shift
      );
    }
  }
  if (!(integral > 0)) {
    return negative_infinity();
  }
  return log_shift + log(integral);
}
real primarycensored_gumbel_numeric_lcdf(data real d, int dist_id,
                                         array[] real params,
                                         data real pwindow, real mu,
                                         real beta) {
  if (dist_has_positive_support(dist_id) && d <= 0) {
    return negative_infinity();
  }
  real log_cdf = mu >= pwindow
    ? gumbel_numeric_spike_lcdf(d | dist_id, params, pwindow, mu, beta)
    : gumbel_numeric_z_lcdf(d | dist_id, params, pwindow, mu, beta);
  if (is_nan(log_cdf)) {
    return negative_infinity();
  }
  return fmin(log_cdf, 0);
}
real primarycensored_gumbel_numeric_cdf(data real d, int dist_id,
                                        array[] real params,
                                        data real pwindow, real mu,
                                        real beta) {
  return exp(primarycensored_gumbel_numeric_lcdf(
    d | dist_id, params, pwindow, mu, beta
  ));
}
int gumbel_series_accepted(vector fit) {
  return fit[2] <= 1e-8;
}
vector primarycensored_gumbel_terms(real t, int dist_id, real beta,
                                    int n_terms, array[] real params) {
  vector[2 * (n_terms + 1)] terms;
  real inv_beta = inv(beta);
  for (n in 0:n_terms) {
    terms[(2 * n + 1):(2 * n + 2)] = log_tilt_transform_pair(
      t, dist_id, n * inv_beta, params
    )[1:2];
  }
  return terms;
}
real gumbel_finite_abs(real x) {
  return is_inf(x) || is_nan(x) ? 0 : abs(x);
}
vector primarycensored_gumbel_lcdf_from_terms(vector terms_d, vector terms_q,
                                              data real d,
                                              data real pwindow, real mu,
                                              real beta, int n_terms) {
  real log_s0 = mu / beta;
  real log_c = -(d - mu) / beta;
  real log_f_q = terms_q[1];
  real log_delta0 = primarycensored_tail_diff(
    terms_d[1], terms_q[1], terms_d[2], terms_q[2]
  );
  // No delay mass in the window, so every term vanishes together
  if (log_delta0 == negative_infinity()) {
    return [log_f_q, 0]';
  }
  real log_pos = log1m_exp(-exp(log_s0)) + log_delta0;
  real log_neg = negative_infinity();
  real scale = 0;
  for (n in 1:n_terms) {
    int i = 2 * n + 1;
    real log_delta = primarycensored_tail_diff(
      terms_d[i], terms_q[i], terms_d[i + 1], terms_q[i + 1]
    );
    real log_a = n * log_c + log_delta - lgamma(n + 1);
    if (n % 2 == 1) {
      log_neg = gumbel_log_sum_exp(log_neg, log_a);
    } else {
      log_pos = gumbel_log_sum_exp(log_pos, log_a);
    }
    scale = fmax(
      scale,
      n * abs(log_c) + fmax(
        fmax(gumbel_finite_abs(terms_d[i]), gumbel_finite_abs(terms_d[i + 1])),
        fmax(gumbel_finite_abs(terms_q[i]), gumbel_finite_abs(terms_q[i + 1]))
      )
    );
  }
  real log_bracket = primarycensored_log_diff_exp(log_pos, log_neg);
  // log D = -s_w + log(1 - exp(-delta)), delta = s_w (exp(w / beta) - 1)
  real log_s_w = -(pwindow - mu) / beta;
  real log_d = -exp(log_s_w)
               + log1m_exp(-exp(log_s_w + log_diff_exp(pwindow / beta, 0)));
  real error;
  if (log_bracket == negative_infinity()) {
    error = positive_infinity();
  } else {
    int n_last = n_terms + 1;
    real log_rounding = log(machine_precision()) + log1p(scale)
                        + gumbel_log_sum_exp(log_pos, log_neg) - log_bracket;
    real log_trunc = log_delta0 + n_last * log_s0 - lgamma(n_last + 1)
                     - log1m(fmin(exp(log_s0) / (n_last + 1), 0.5))
                     - log_bracket;
    error = exp(log_rounding) + exp(log_trunc);
  }
  real log_cdf = gumbel_log_sum_exp(log_f_q, log_bracket - log_d);
  return [fmin(log_cdf, 0), error]';
}
real primarycensored_gumbel_lcdf(data real d, int dist_id,
                                 array[] real params, data real pwindow,
                                 real mu, real beta) {
  int n_terms = gumbel_n_terms(mu / beta);
  vector[2] fit = primarycensored_gumbel_lcdf_from_terms(
    primarycensored_gumbel_terms(d, dist_id, beta, n_terms, params),
    primarycensored_gumbel_terms(d - pwindow, dist_id, beta, n_terms, params),
    d, pwindow, mu, beta, n_terms
  );
  if (gumbel_series_accepted(fit)) {
    return fit[1];
  }
  return primarycensored_gumbel_numeric_lcdf(
    d | dist_id, params, pwindow, mu, beta
  );
}
int dist_has_positive_support(data int dist_id) {
  if (dist_id == 1) return 1;   // Lognormal
  if (dist_id == 2) return 1;   // Gamma
  if (dist_id == 3) return 1;   // Weibull
  if (dist_id == 4) return 1;   // Exponential
  if (dist_id == 5) return 1;   // Generalised gamma
  if (dist_id == 9) return 1;   // Beta (support on [0, 1])
  if (dist_id == 13) return 1;  // Chi-square
  if (dist_id == 16) return 1;  // Inverse Gamma
  if (dist_id == 19) return 1;  // Inverse Chi-square
  if (dist_id == 21) return 1;  // Pareto
  if (dist_id == 22) return 1;  // Scaled inverse Chi-square
  if (dist_id == 29) return 1;  // Log-logistic
  return 0;
}
real gamma_lcdf_logx(real log_x, real a) {
  if (!(a > 0) || is_inf(a)) {
    reject("gamma_lcdf_logx: shape must be positive finite, found ", a);
  }
  real x = exp(log_x);
  if (!(x < 0.5 * (a + 1))) {
    return gamma_lcdf(x | a, 1);
  }
  // Each term is at most half the one before
  real term = 1;
  real total = 1;
  real n = a;
  while (term > 1e-16 * total) {
    n += 1;
    term *= x / n;
    total += term;
  }
  return a * log_x - x - lgamma(a + 1) + log(total);
}
vector gamma_lcdf_lccdf_logx(real log_x, real a) {
  if (!(a > 0) || is_inf(a)) {
    reject("gamma_lcdf_lccdf_logx: shape must be positive finite, found ", a);
  }
  real x = exp(log_x);
  if (!(x >= a + 1)) {
    real log_p = gamma_lcdf_logx(log_x, a);
    return [log_p, log1m_exp(log_p)]';
  }
  if (is_inf(x)) return [0, negative_infinity()]';
  real b = x + 1 - a;
  real c = 1e300;
  real d = 1 / b;
  real h = d;
  real delta = 1;
  // err bounds |delta - 1|. Flooring |i - a| at 1 keeps it above 0 at an
  // integer shape, where the fraction ends but its shape gradient does not.
  real err = 1;
  int i = 0;
  while (err >= 1e-15) {
    i += 1;
    real an = -i * (i - a);
    real d_prev = d;
    b += 2;
    d = an * d + b;
    if (abs(d) < 1e-300) d = 1e-300;
    c = b + an / c;
    if (abs(c) < 1e-300) c = 1e-300;
    d = 1 / d;
    err *= i * fmax(abs(i - a), 1) * abs(d * d_prev / delta);
    delta = d * c;
    h *= delta;
  }
  real log_q = a * log_x - x - lgamma(a) + log(h);
  return [log1m_exp(log_q), log_q]';
}
real gamma_log_rate(real rate) {
  if (!(rate > 0) || is_inf(rate)) {
    reject("Gamma rate must be positive finite, found ", rate);
  }
  return log(rate);
}
real gengamma_lcdf(real y, real shape, real scale, real k) {
  if (y < 0) {
    reject("gengamma_lcdf: y must be non-negative, found y = ", y);
  }
  if (y == 0) {
    return negative_infinity();
  }
  return gamma_lcdf_logx(shape * (log(y) - log(scale)), k);
}
int lognormal_lcdf_underflows(real y, real mu, real sigma) {
  if (y <= 0) {
    return 1;
  }
  return (log(y) - mu) / sigma < -38 ? 1 : 0;
}
real dist_lcdf(real delay, array[] real params, int dist_id) {
  if (dist_has_positive_support(dist_id) && delay <= 0) {
    return negative_infinity();
  }

  // IDs match pcd_distributions$stan_id in R
  // Guarded so a lower-tail underflow cannot put a NaN partial on the tape.
  // The downstream `exp(-inf)` differentiates to 0.
  if (dist_id == 1) {
    return lognormal_lcdf_underflows(delay, params[1], params[2])
           ? negative_infinity()
           : lognormal_lcdf(delay | params[1], params[2]);
  }
  else if (dist_id == 2) {
    return gamma_lcdf_logx(log(delay) + gamma_log_rate(params[2]), params[1]);
  }
  else if (dist_id == 3) return weibull_lcdf(delay | params[1], params[2]);
  else if (dist_id == 4) return exponential_lcdf(delay | params[1]);
  else if (dist_id == 5) return gengamma_lcdf(delay | params[1], params[2], params[3]);
  else if (dist_id == 9) return beta_lcdf(delay | params[1], params[2]);
  else if (dist_id == 12) return cauchy_lcdf(delay | params[1], params[2]);
  else if (dist_id == 13) return chi_square_lcdf(delay | params[1]);
  else if (dist_id == 15) return gumbel_lcdf(delay | params[1], params[2]);
  else if (dist_id == 16) return inv_gamma_lcdf(delay | params[1], params[2]);
  else if (dist_id == 17) return logistic_lcdf(delay | params[1], params[2]);
  else if (dist_id == 18) return normal_lcdf(delay | params[1], params[2]);
  else if (dist_id == 19) return inv_chi_square_lcdf(delay | params[1]);
  else if (dist_id == 20) return double_exponential_lcdf(delay | params[1], params[2]);
  else if (dist_id == 21) return pareto_lcdf(delay | params[1], params[2]);
  else if (dist_id == 22) return scaled_inv_chi_square_lcdf(delay | params[1], params[2]);
  else if (dist_id == 23) return student_t_lcdf(delay | params[1], params[2], params[3]);
  else if (dist_id == 24) return uniform_lcdf(delay | params[1], params[2]);
  else if (dist_id == 25) return von_mises_lcdf(delay | params[1], params[2]);
  else if (dist_id == 29) {
    return primarycensored_loglogistic_lcdf(delay | params[1], params[2]);
  }
  else if (dist_id == 26) {
    // Non-parametric step: params = [boundaries (K+1), pmf (K)].
    int K = (size(params) - 1) %/% 2;
    return pstep_lcdf(
      delay | to_vector(segment(params, 1, K + 1)),
              to_vector(segment(params, K + 2, K))
    );
  }
  else if (dist_id == 27 || dist_id == 28) {
    // Non-parametric discrete hazard: params = [boundaries (K+1),
    // hazards (K)] with hazards[K] = 1. RW (27) and RE (28) share the
    // same likelihood; they only differ in the prior.
    int K = (size(params) - 1) %/% 2;
    return phazard_lcdf(
      delay | to_vector(segment(params, 1, K + 1)),
              to_vector(segment(params, K + 2, K))
    );
  }
  else reject("Invalid distribution identifier: ", dist_id);
}
real primary_lpdf(real x, int primary_id, array[] real params, real xmin, real xmax) {
  // Implement switch for different primary distributions
  if (primary_id == 1) return uniform_lpdf(x | xmin, xmax);
  if (primary_id == 2) return expgrowth_lpdf(x | xmin, xmax, params[1]);
  if (primary_id == 3) {
    return tlogis_lpdf(x | xmin, xmax, params[1], params[2]);
  }
  if (primary_id == 4) {
    return tgumbel_lpdf(x | xmin, xmax, params[1], params[2]);
  }
  // Add more primary distributions as needed
  reject("Invalid primary distribution identifier");
}
vector primarycensored_ode(real t, vector y, array[] real theta,
                            array[] real x_r, array[] int x_i) {
  real d = x_r[1];
  int dist_id = x_i[1];
  int primary_id = x_i[2];
  real pwindow = x_r[2];
  int dist_params_len = x_i[3];
  int primary_params_len = x_i[4];

  // Extract distribution parameters
  array[dist_params_len] real params;
  if (dist_params_len) {
    params = theta[1:dist_params_len];
  }
  array[primary_params_len] real primary_params;
  if (primary_params_len) {
    int primary_loc = num_elements(theta);
    primary_params = theta[primary_loc - primary_params_len + 1:primary_loc];
  }

  real log_cdf = dist_lcdf(t | params, dist_id);
  real log_primary_pdf = primary_lpdf(d - t | primary_id, primary_params, 0, pwindow);

  return rep_vector(exp(log_cdf + log_primary_pdf), 1);
}
real primary_lcdf(real p, int primary_id, array[] real primary_params,
                  data real pwindow) {
  if (primary_id == 1) {
    // Uniform on [0, pwindow]: built-in uniform_lcdf matches the package
    // primary semantics over [0, pwindow].
    if (p <= 0) return negative_infinity();
    if (p >= pwindow) return 0;
    return uniform_lcdf(p | 0, pwindow);
  } else if (primary_id == 2) {
    return expgrowth_lcdf(p | 0, pwindow, primary_params[1]);
  } else if (primary_id == 3) {
    return tlogis_lcdf(p | 0, pwindow, primary_params[1], primary_params[2]);
  } else if (primary_id == 4) {
    return tgumbel_lcdf(p | 0, pwindow, primary_params[1], primary_params[2]);
  }
  reject("primary_lcdf: unsupported primary_id ", primary_id);
}
int check_for_tlogis(int dist_id, int primary_id) {
  return primary_id == 3 && (dist_id == 2 || dist_id == 4 || dist_id == 18);
}
real tlogis_log_bound(int n0, int M, real log_lo, real log_hi) {
  if (M == 0) return n0 * log_hi;
  if (n0 == 0) return M * (log1m_exp(log_lo) - log2());
  real log_x = fmin(fmax(log(1.0 * n0 / (n0 + M)), log_lo), log_hi);
  return M * (log1m_exp(log_x) - log2()) + n0 * log_x;
}
array[] int tlogis_series_terms(real log_lo, real log_hi, real log_tol) {
  if (is_inf(log_tol) || is_nan(log_tol)) return {-1, -1};
  for (k in 1:64) {
    int taper = to_int(floor(0.35 * k));
    if (tlogis_log_bound(k, 0, log_lo, log_hi) <= log_tol) return {k, 0};
    if (tlogis_log_bound(taper, k - taper, log_lo, log_hi) <= log_tol) {
      return {taper, k - taper};
    }
    if (tlogis_log_bound(0, k, log_lo, log_hi) <= log_tol) return {0, k};
  }
  return {-1, -1};
}
array[] int tlogis_plan(real location, real scale, data real pwindow,
                        real log_mass) {
  real log_tol = log(1e-10) + log_mass;
  array[2] int pos = {0, 0};
  array[2] int neg = {0, 0};
  int pos_form = 0;
  if (location < 0) {
    pos_form = 1;
    pos = tlogis_series_terms(
      (location - pwindow) / scale, location / scale, log_tol
    );
    if (pos[1] < 0) return {0, 0, 0, 0, 0, 0};
  } else {
    if (location < pwindow) {
      pos_form = 2;
      pos = tlogis_series_terms(-(pwindow - location) / scale, 0, log_tol);
      if (pos[1] < 0) return {0, 0, 0, 0, 0, 0};
    }
    if (location > 0) {
      neg = tlogis_series_terms(
        -location / scale, fmin(0, (pwindow - location) / scale), log_tol
      );
      if (neg[1] < 0) return {0, 0, 0, 0, 0, 0};
    }
  }
  return {1, pos_form, pos[1], pos[2], neg[1], neg[2]};
}
int tlogis_is_valid(real location, real scale, data real pwindow) {
  if (!(pwindow > 0) || is_inf(pwindow)) return 0;
  return scale > 0 && !is_inf(scale) && !is_nan(location)
         && !is_inf(location);
}
int tlogis_n_pos(array[] int plan) {
  if (plan[2] == 0) return 0;
  return plan[3] + plan[4] - (plan[2] == 2 ? 1 : 0);
}
int tlogis_n_neg(array[] int plan) {
  return plan[5] + plan[6];
}
int tlogis_plan_applies(int dist_id, array[] real params, real scale,
                        array[] int plan) {
  if (plan[1] == 0) return 0;
  if (tlogis_n_pos(plan) > 0
      && !check_for_tilt_transform(
        dist_id, tlogis_n_pos(plan) / scale, params
      )) {
    return 0;
  }
  if (tlogis_n_neg(plan) > 0
      && !check_for_tilt_transform(
        dist_id, -tlogis_n_neg(plan) / scale, params
      )) {
    return 0;
  }
  return 1;
}
int check_for_tlogis_params(int dist_id, array[] real params,
                            array[] real primary_params,
                            data real pwindow) {
  real location = primary_params[1];
  real scale = primary_params[2];
  if (!tlogis_is_valid(location, scale, pwindow)) return 0;
  real log_mass = tlogis_log_mass(0, pwindow, location, scale);
  return tlogis_plan_applies(
    dist_id, params, scale, tlogis_plan(location, scale, pwindow, log_mass)
  );
}
vector tlogis_weights(int n0, int M) {
  vector[n0 + M] weights = rep_vector(1, n0 + M);
  real tail = 0;
  // The upper tail from the top, so that small weights keep their precision
  for (i in 1:M) {
    int top = M - i + 1;
    tail += exp(lchoose(M, top) - M * log2());
    weights[n0 + top] = tail;
  }
  return weights;
}
matrix primarycensored_tlogis_terms(real t, int dist_id, array[] real params,
                                    real scale, int n_pos, int n_neg,
                                    int use_pos, int use_neg) {
  matrix[2, 1 + n_pos + n_neg] terms = rep_matrix(0, 2, 1 + n_pos + n_neg);
  terms[, 1] = log_tilt_transform_pair(t, dist_id, 0, params)[1:2];
  if (use_pos) {
    for (n in 1:n_pos) {
      terms[, 1 + n] = log_tilt_transform_pair(
        t, dist_id, n / scale, params
      )[1:2];
    }
  }
  if (use_neg) {
    for (n in 1:n_neg) {
      terms[, 1 + n_pos + n] = log_tilt_transform_pair(
        t, dist_id, -n / scale, params
      )[1:2];
    }
  }
  return terms;
}
real tlogis_terms_diff(matrix terms_hi, matrix terms_lo, int column) {
  return primarycensored_tail_diff(
    terms_hi[1, column], terms_lo[1, column],
    terms_hi[2, column], terms_lo[2, column]
  );
}
real tlogis_weighted_sum(vector log_c, vector weights, real log_scale) {
  int n = rows(weights);
  real total = 0;
  for (i in 1:n) {
    total += (i % 2 == 1 ? 1 : -1) * weights[i] * exp(log_c[i] - log_scale);
  }
  return total;
}
vector tlogis_part_before_window(matrix terms_a, matrix terms_d,
                                 data real d, real location, real scale,
                                 vector weights) {
  int n = rows(weights);
  real log_df = tlogis_terms_diff(terms_d, terms_a, 1);
  vector[n] log_c;
  for (k in 1:n) {
    log_c[k] = k * location / scale + primarycensored_log_diff_exp(
      log_df, -k * d / scale + tlogis_terms_diff(terms_d, terms_a, 1 + k)
    );
  }
  real log_scale = max(log_c);
  if (is_inf(log_scale)) return [0, 0]';
  return [log_scale, tlogis_weighted_sum(log_c, weights, log_scale)]';
}
vector tlogis_part_above_location(matrix terms_a, matrix terms_u,
                                  data real d, real location, real scale,
                                  vector weights) {
  int n = rows(weights);
  real log_df = tlogis_terms_diff(terms_u, terms_a, 1);
  vector[n] log_c;
  for (k in 0:(n - 1)) {
    log_c[k + 1] = (k == 0 ? log_df
                           : tlogis_terms_diff(terms_u, terms_a, 1 + k))
                   - k * (d - location) / scale;
  }
  // The constant term of the series, L(0) times the mass of the delay
  real log_constant = log_inv_logit(-location / scale) + log_df;
  real log_scale = fmax(max(log_c), log_constant);
  if (is_inf(log_scale)) return [0, 0]';
  return [
    log_scale,
    tlogis_weighted_sum(log_c, weights, log_scale)
    - exp(log_constant - log_scale)
  ]';
}
vector tlogis_part_below_location(matrix terms_u, matrix terms_d, int n_pos,
                                  data real d, real location, real scale,
                                  vector weights) {
  int n = rows(weights);
  real log_df = tlogis_terms_diff(terms_d, terms_u, 1);
  vector[n] log_c;
  for (k in 1:n) {
    log_c[k] = -k * location / scale + primarycensored_log_diff_exp(
      k * d / scale + tlogis_terms_diff(terms_d, terms_u, 1 + n_pos + k),
      log_df
    );
  }
  real log_scale = max(log_c);
  if (is_inf(log_scale)) return [0, 0]';
  return [log_scale, tlogis_weighted_sum(log_c, weights, log_scale)]';
}
real primarycensored_tlogis_lcdf_from_terms(
  matrix terms_a, matrix terms_u, matrix terms_d, data real d, real location,
  real scale, real log_mass, array[] int plan, vector w_pos, vector w_neg
) {
  real log_phi = negative_infinity();
  if (plan[2] == 1) {
    vector[2] part = tlogis_part_before_window(
      terms_a, terms_d, d, location, scale, w_pos
    );
    if (part[2] > 0) log_phi = part[1] + log(part[2]);
  } else if (plan[2] == 2) {
    vector[2] part = tlogis_part_above_location(
      terms_a, terms_u, d, location, scale, w_pos
    );
    if (part[2] > 0) log_phi = part[1] + log(part[2]);
  }
  if (tlogis_n_neg(plan) > 0) {
    vector[2] part = tlogis_part_below_location(
      terms_u, terms_d, tlogis_n_pos(plan), d, location, scale, w_neg
    );
    if (part[2] > 0) log_phi = log_sum_exp(log_phi, part[1] + log(part[2]));
  }
  real log_f_a = terms_a[1, 1];
  // Deep enough into the lower tail every term underflows together. Both
  // are then `-inf` and log_sum_exp would differentiate to NaN.
  if (log_f_a == negative_infinity() && log_phi == negative_infinity()) {
    return negative_infinity();
  }
  // The CDF is at most 1. Rounding can put the log CDF a little above 0.
  return fmin(log_sum_exp(log_f_a, log_phi - log_mass), 0);
}
int tlogis_is_small_delay(int dist_id, data real d, data real pwindow,
                          real scale) {
  return dist_has_positive_support(dist_id) && d > 0 && d < pwindow
         && d < 1e-4 * scale;
}
real primarycensored_tlogis_small_delay_lcdf(data real d, int dist_id,
                                             array[] real params,
                                             real location, real scale,
                                             real log_mass) {
  vector[3] moments = primarycensored_tilt_moments(d, dist_id, params);
  if (moments[1] == negative_infinity()) return negative_infinity();
  real log_l1 = log_inv_logit(-location / scale)
                + log_inv_logit(location / scale) - log(scale);
  real ratio = (1 - 2 * inv_logit(-location / scale)) / scale;
  return fmin(
    moments[1] + log_l1 - log_mass
    + log1p(0.5 * ratio * exp(moments[2] - moments[1])),
    0
  );
}
real primarycensored_tlogis_lcdf(data real d, int dist_id,
                                 array[] real params, data real pwindow,
                                 real location, real scale) {
  if (dist_has_positive_support(dist_id) && d <= 0) {
    return negative_infinity();
  }
  if (!tlogis_is_valid(location, scale, pwindow)) {
    reject("The truncated logistic solution needs a finite location, ",
           "and a positive finite scale and window.");
  }
  real log_mass = tlogis_log_mass(0, pwindow, location, scale);
  array[6] int plan = tlogis_plan(location, scale, pwindow, log_mass);
  if (!tlogis_plan_applies(dist_id, params, scale, plan)) {
    reject(
      "The truncated logistic solution does not apply for location ",
      location, ", scale ", scale, " and window ", pwindow,
      ". Use the numerical path, see check_for_analytical_params()."
    );
  }
  if (tlogis_is_small_delay(dist_id, d, pwindow, scale)) {
    return primarycensored_tlogis_small_delay_lcdf(
      d | dist_id, params, location, scale, log_mass
    );
  }
  int n_pos = tlogis_n_pos(plan);
  int n_neg = tlogis_n_neg(plan);
  int has_pos = plan[2] > 0;
  int has_neg = n_neg > 0;
  vector[plan[3] + plan[4]] w_pos = tlogis_weights(plan[3], plan[4]);
  vector[plan[5] + plan[6]] w_neg = tlogis_weights(plan[5], plan[6]);
  real a = d - pwindow;
  // The split point is d for a location at most 0 and a at least pwindow
  int u_is_d = location <= 0;
  int u_is_a = location >= pwindow;
  matrix[2, 1 + n_pos + n_neg] terms_a = primarycensored_tlogis_terms(
    a, dist_id, params, scale, n_pos, n_neg, has_pos, has_neg && u_is_a
  );
  matrix[2, 1 + n_pos + n_neg] terms_d = primarycensored_tlogis_terms(
    d, dist_id, params, scale, n_pos, n_neg, has_pos && u_is_d, has_neg
  );
  if (u_is_d) {
    return primarycensored_tlogis_lcdf_from_terms(
      terms_a, terms_d, terms_d, d, location, scale, log_mass, plan, w_pos,
      w_neg
    );
  } else if (u_is_a) {
    return primarycensored_tlogis_lcdf_from_terms(
      terms_a, terms_a, terms_d, d, location, scale, log_mass, plan, w_pos,
      w_neg
    );
  }
  return primarycensored_tlogis_lcdf_from_terms(
    terms_a,
    primarycensored_tlogis_terms(
      d - location, dist_id, params, scale, n_pos, n_neg, has_pos, has_neg
    ),
    terms_d, d, location, scale, log_mass, plan, w_pos, w_neg
  );
}
real primarycensored_numeric_cdf(data real d, data int dist_id,
                                 array[] real params, data real pwindow,
                                 data int primary_id,
                                 array[] real primary_params) {
  if (primary_id == 4) {
    return primarycensored_gumbel_numeric_cdf(
      d | dist_id, params, pwindow, primary_params[1], primary_params[2]
    );
  }
  real lower_bound = dist_has_positive_support(dist_id)
                     ? fmax(d - pwindow, 0) : d - pwindow;
  int n_params = num_elements(params);
  int n_primary_params = num_elements(primary_params);
  array[n_params + n_primary_params] real theta = append_array(
    params, primary_params
  );
  array[4] int ids = {dist_id, primary_id, n_params, n_primary_params};

  vector[1] y = rep_vector(0.0, 1);
  if (primary_id != 3) {
    return ode_rk45(
      primarycensored_ode, y, lower_bound, {d}, theta, {d, pwindow}, ids
    )[1, 1];
  }
  // Solve in parts around a narrow truncated logistic density, with tighter
  // tolerances, so that the solver does not step over it
  vector[12] stops = append_row(
    tlogis_spike_times(d, pwindow, primary_params[1], primary_params[2]), d
  );
  real start = lower_bound;
  for (i in 1:12) {
    if (i < 12 && (stops[i] <= start || stops[i] >= d)) continue;
    y = ode_rk45_tol(
      primarycensored_ode, y, start, {stops[i]}, 1e-9, 1e-10, 1000000,
      theta, {d, pwindow}, ids
    )[1];
    start = stops[i];
  }
  return y[1];
}
real primarycensored_log_normalizer(real log_cdf_D, real log_cdf_L, real L) {
  if (!is_inf(L)) {
    return log_diff_exp(log_cdf_D, log_cdf_L);
  } else {
    return log_cdf_D;
  }
}
real primarycensored_apply_truncation(real log_cdf, real log_cdf_L,
                                      real log_normalizer, real L) {
  if (!is_inf(L)) {
    return log_diff_exp(log_cdf, log_cdf_L) - log_normalizer;
  } else {
    return log_cdf - log_normalizer;
  }
}
vector primarycensored_truncation_bounds(
  data real L, data real D,
  data int dist_id, array[] real params, data real pwindow,
  data int primary_id, array[] real primary_params
) {
  vector[2] result;
  // Internal lower bound for the un-truncated distribution: 0 lets the
  // `d <= L` early-exit in primarycensored_lcdf return -inf for delays below
  // the natural support of positive-support distributions; -inf disables that
  // short-circuit so distributions with support on the reals are integrated.
  // Expression is inlined (rather than bound to a local) so Stan's data-flow
  // checker recognises it as data-only.

  // Get CDF at lower truncation point L
  if (is_inf(L)) {
    result[1] = negative_infinity();
  } else {
    result[1] = primarycensored_lcdf(
      L | dist_id, params, pwindow,
      dist_has_positive_support(dist_id) ? 0.0 : negative_infinity(),
      positive_infinity(), primary_id, primary_params
    );
  }

  // Get CDF at upper truncation point D
  if (is_inf(D)) {
    result[2] = 0;
  } else {
    result[2] = primarycensored_lcdf(
      D | dist_id, params, pwindow,
      dist_has_positive_support(dist_id) ? 0.0 : negative_infinity(),
      positive_infinity(), primary_id, primary_params
    );
  }

  return result;
}
real primarycensored_cdf(data real d, data int dist_id, array[] real params,
                               data real pwindow, data real L, data real D,
                               data int primary_id,
                               array[] real primary_params) {
  real result;
  if (d <= L) {
    return 0;
  }

  if (d >= D) {
    return 1;
  }

  // Check if an analytical solution exists and applies for these parameters
  if (check_for_analytical_delay(dist_id, params, primary_id,
                                 primary_params, d, pwindow)) {
    // Use analytical solution
    result = primarycensored_analytical_cdf(
      d | dist_id, params, pwindow, L, D, primary_id, primary_params
    );
  } else {
    // Use numerical integration for other cases. For positive-support
    // delays the integral is 0 for d <= 0.
    if (dist_has_positive_support(dist_id) && d <= 0) {
      return 0;
    }
    result = primarycensored_numeric_cdf(
      d | dist_id, params, pwindow, primary_id, primary_params
    );

    // Apply truncation normalization on log scale for numerical stability.
    // Skip when F(L) = 0 makes it a no-op (positive support, L <= 0).
    if (!is_inf(D) || L > 0 ||
        (!is_inf(L) && !dist_has_positive_support(dist_id))) {
      real log_result = log(result);
      vector[2] bounds = primarycensored_truncation_bounds(
        L, D, dist_id, params, pwindow, primary_id, primary_params
      );
      real log_cdf_L = bounds[1];
      real log_cdf_D = bounds[2];

      real log_normalizer = primarycensored_log_normalizer(log_cdf_D, log_cdf_L, L);
      log_result = primarycensored_apply_truncation(
        log_result, log_cdf_L, log_normalizer, L
      );
      result = exp(log_result);
    }
  }

  return result;
}
real primarycensored_lcdf(data real d, data int dist_id, array[] real params,
                                data real pwindow, data real L, data real D,
                                data int primary_id,
                                array[] real primary_params) {
  real result;

  if (d <= L) {
    return negative_infinity();
  }

  if (d >= D) {
    return 0;
  }

  // Check if an analytical solution exists. The internal lower bound is 0 for
  // positive-support delays (lets the d <= L early-exit return -inf for d <= 0)
  // and -inf for distributions with support on the reals.
  if (check_for_analytical_delay(dist_id, params, primary_id,
                                 primary_params, d, pwindow)) {
    result = primarycensored_analytical_lcdf(
      d | dist_id, params, pwindow,
      dist_has_positive_support(dist_id) ? 0.0 : negative_infinity(),
      positive_infinity(), primary_id, primary_params
    );
  } else {
    // Use numerical integration
    if (primary_id == 4) {
      // The truncated Gumbel integral is on the log scale, so a CDF below
      // 1e-300 is not lost
      result = primarycensored_gumbel_numeric_lcdf(
        d | dist_id, params, pwindow, primary_params[1], primary_params[2]
      );
    } else {
      result = log(primarycensored_cdf(
        d | dist_id, params, pwindow,
        dist_has_positive_support(dist_id) ? 0.0 : negative_infinity(),
        positive_infinity(), primary_id, primary_params
      ));
    }
  }

  // Handle truncation normalization. Skip when F(L) = 0 makes it a no-op
  // (positive support, L <= 0) to avoid the cancelling log_diff_exp.
  if (!is_inf(D) || L > 0 ||
      (!is_inf(L) && !dist_has_positive_support(dist_id))) {
    vector[2] bounds = primarycensored_truncation_bounds(
      L, D, dist_id, params, pwindow, primary_id, primary_params
    );
    real log_cdf_L = bounds[1];
    real log_cdf_D = bounds[2];

    real log_normalizer = primarycensored_log_normalizer(log_cdf_D, log_cdf_L, L);
    result = primarycensored_apply_truncation(result, log_cdf_L, log_normalizer, L);
  }

  return result;
}
real primarycensored_lpmf(data int d, data int dist_id, array[] real params,
                                data real pwindow, data real d_upper,
                                data real L, data real D, data int primary_id,
                                array[] real primary_params) {
  if (d_upper > D) {
    reject("Upper truncation point is greater than D. It is ", d_upper,
           " and D is ", D, ". Resolve this by increasing D to be greater or equal to d + swindow or decreasing swindow.");
  }
  if (d_upper <= d) {
    reject("Upper truncation point is less than or equal to d. It is ", d_upper,
           " and d is ", d, ". Resolve this by increasing d to be less than d_upper.");
  }
  if (d < L) {
    return negative_infinity();
  }
  real log_cdf_upper;
  real log_cdf_lower;
  if (check_for_exptilt(dist_id, primary_id)
      && check_for_analytical_delay(dist_id, params, primary_id,
                                    primary_params, d_upper, pwindow)
      && check_for_analytical_delay(dist_id, params, primary_id,
                                    primary_params, d, pwindow)) {
    // Share the tilt quantities of the two analytical evaluations
    vector[2] log_cdfs = primarycensored_exptilt_lcdf_pair(
      d, d_upper, dist_id, params, pwindow, primary_params[1]
    );
    log_cdf_lower = log_cdfs[1];
    log_cdf_upper = log_cdfs[2];
  } else {
    log_cdf_upper = primarycensored_lcdf(
      d_upper | dist_id, params, pwindow,
      dist_has_positive_support(dist_id) ? 0.0 : negative_infinity(),
      positive_infinity(), primary_id, primary_params
    );
    log_cdf_lower = primarycensored_lcdf(
      d | dist_id, params, pwindow,
      dist_has_positive_support(dist_id) ? 0.0 : negative_infinity(),
      positive_infinity(), primary_id, primary_params
    );
  }

  // Apply truncation normalization: log((F(d_upper) - F(d)) / (F(D) - F(L))).
  // Skip when F(L) = 0 makes it a no-op (positive support, L <= 0).
  if (!is_inf(D) || L > 0 ||
      (!is_inf(L) && !dist_has_positive_support(dist_id))) {
    real log_cdf_D;
    real log_cdf_L;

    // Get CDF at lower truncation point L
    if (is_inf(L)) {
      // No left truncation (L = -inf sentinel)
      log_cdf_L = negative_infinity();
    } else if (d == L) {
      // Reuse already computed CDF at d
      log_cdf_L = log_cdf_lower;
    } else {
      // Compute CDF at L directly
      log_cdf_L = primarycensored_lcdf(
        L | dist_id, params, pwindow,
        dist_has_positive_support(dist_id) ? 0.0 : negative_infinity(),
        positive_infinity(), primary_id, primary_params
      );
    }

    // Get CDF at upper truncation point D
    if (d_upper == D) {
      log_cdf_D = log_cdf_upper;
    } else if (is_inf(D)) {
      log_cdf_D = 0;
    } else {
      log_cdf_D = primarycensored_lcdf(
        D | dist_id, params, pwindow,
        dist_has_positive_support(dist_id) ? 0.0 : negative_infinity(),
        positive_infinity(), primary_id, primary_params
      );
    }

    real log_normalizer = primarycensored_log_normalizer(log_cdf_D, log_cdf_L, L);
    return log_diff_exp(log_cdf_upper, log_cdf_lower) - log_normalizer;
  } else {
    return log_diff_exp(log_cdf_upper, log_cdf_lower);
  }
}
real tgumbel_log_delta_window(real xmin, real xmax, real mu, real beta) {
  return -(xmax - mu) / beta + log_diff_exp((xmax - xmin) / beta, 0);
}
real tgumbel_log1m_exp_neg_exp(real x) {
  if (x < -37) {
    return x;
  }
  if (x > 700) {
    return 0;
  }
  return log1m_exp(-exp(x));
}
real tgumbel_log_norm(real xmin, real xmax, real mu, real beta) {
  return tgumbel_log1m_exp_neg_exp(
    tgumbel_log_delta_window(xmin, xmax, mu, beta)
  );
}
real tgumbel_lpdf(real x, real xmin, real xmax, real mu, real beta) {
  if (x < xmin || x > xmax) {
    return negative_infinity();
  }
  real log_s = -(x - mu) / beta;
  real exponent = 0;
  if (x < xmax) {
    exponent = exp(-(xmax - mu) / beta + log_diff_exp((xmax - x) / beta, 0));
  }
  return -log(beta) + log_s - exponent - tgumbel_log_norm(xmin, xmax, mu, beta);
}
real tgumbel_lcdf(real x, real xmin, real xmax, real mu, real beta) {
  if (x <= xmin) {
    return negative_infinity();
  }
  if (x >= xmax) {
    return 0;
  }
  real log_delta_window = tgumbel_log_delta_window(xmin, xmax, mu, beta);
  real log_delta_lower = -(x - mu) / beta
                         + log_diff_exp((x - xmin) / beta, 0);
  real log_delta_upper = -(xmax - mu) / beta
                         + log_diff_exp((xmax - x) / beta, 0);
  real log_norm = tgumbel_log1m_exp_neg_exp(log_delta_window);
  return tgumbel_log1m_exp_neg_exp(log_delta_lower) - exp(log_delta_upper)
         - log_norm;
}
real tlogis_log_mass(real lo, real hi, real location, real scale) {
  if (lo >= location) {
    return primarycensored_log_diff_exp(
      log_inv_logit(-(lo - location) / scale),
      log_inv_logit(-(hi - location) / scale)
    );
  }
  return primarycensored_log_diff_exp(
    log_inv_logit((hi - location) / scale),
    log_inv_logit((lo - location) / scale)
  );
}
real tlogis_lpdf(real x, real xmin, real xmax, real location, real scale) {
  if (x < xmin || x > xmax) {
    return negative_infinity();
  }
  return logistic_lpdf(x | location, scale)
         - tlogis_log_mass(xmin, xmax, location, scale);
}
vector tlogis_spike_times(data real d, data real pwindow, real location,
                          real scale) {
  vector[11] multiples = [30, 12, 6, 3, 1.5, 0, -1.5, -3, -6, -12, -30]';
  return d - (fmin(fmax(location, 0), pwindow) + scale * multiples);
}
real tlogis_lcdf(real x, real xmin, real xmax, real location, real scale) {
  if (x <= xmin) {
    return negative_infinity();
  }
  if (x >= xmax) {
    return 0;
  }
  return tlogis_log_mass(xmin, x, location, scale)
         - tlogis_log_mass(xmin, xmax, location, scale);
}"
